    removeListener(event: "connectionstatechange", listener: (ev: FIBJS.GeneralObject)=>void): this;

    addEventListener(event: "connectionstatechange", listener: (ev: FIBJS.GeneralObject)=>void, options?: FIBJS.GeneralObject): this;

